  join operations o on o.client_key = md5(t.key)::uuid and o.business_id = t.id
  join reviews r on r.operation_id = o.id and r.status <> 'removed'
 where r.user_id <> (select u.id from users u where u.phone = t.u)
   and not exists (select 1 from review_helpful h where h.review_id = r.id and h.user_id = (select u.id from users u where u.phone = t.u));
update reviews r set helpful_count = (select count(*) from review_helpful h where h.review_id = r.id)
 where r.business_id = any(array['barberia-la-esquina-fresca-hazleton','los-duros-del-fade-allentown','barberia-tres-coronas-wilkes-barre','el-taller-del-barbero-scranton','fade-kings-latino-reading','barberia-don-chepe-hazleton','navaja-y-estilo-allentown','barberia-el-maestro-fino-wilkes-barre','cortes-criollos-scranton','barberia-patio-quisqueyano-reading','barbero-en-casa-allentown','domicilio-fino-cuts-wilkes-barre','tijeras-moviles-scranton','el-barbero-ambulante-reading','corte-a-la-puerta-hazleton','barberia-movil-el-gallo-allentown','fade-a-domicilio-jr-wilkes-barre','tu-barbero-contigo-scranton','cortes-sobre-ruedas-reading','barbero-express-familiar-hazleton','peluqueria-pequenos-reyes-wilkes-barre','mini-fade-kids-scranton','cortecitos-felices-reading','el-rincon-del-chamaquito-hazleton','barberia-los-principitos-allentown','pelo-de-angel-kids-wilkes-barre','tijeritas-de-oro-scranton','cuarto-de-barbero-junior-reading','corte-chiquitin-hazleton','barbitas-y-bigotes-infantil-allentown','la-barba-del-patron-scranton','barba-fina-studio-reading','caballeros-del-filo-hazleton','navaja-de-oro-caballeros-allentown','barberia-don-facundo-wilkes-barre','el-arreglo-perfecto-scranton','barba-y-bigote-boricua-reading','salon-de-caballeros-el-gran-senor-hazleton','filo-y-fino-allentown','barberia-el-bigote-dorado-wilkes-barre','salon-divas-del-caribe-reading','estetica-marisol-hazleton','salon-rizos-y-mas-allentown','belleza-tropical-wilkes-barre','salon-mil-colores-scranton','estilo-latino-beauty-reading','salon-la-reina-del-peinado-hazleton','glamour-dominicano-salon-allentown','salon-yesenia-wilkes-barre','belleza-pura-vida-scranton']::text[]) and r.helpful_count <> (select count(*) from review_helpful h where h.review_id = r.id);
insert into business_posts (business_id, city_id, kind, title, body, link_kind, item_id, price_was_cents, price_now_cents, aviso, poll, audience, publish_at, ends_at, status, pinned, created_by, created_at)
select t.id, t.city, t.kind, t.title, t.body, case when t.it is null then 'none' else 'item' end,
